// Recovered from the July 13 page-size Lantern session (regenerated by transcript replay).
const { JSDOM } = require("jsdom");
const fs = require("fs");
const html = fs.readFileSync(require("path").join(__dirname, "..", "src", "lantern.inner.html"), "utf8");
const dom = new JSDOM(html, { url: "http://localhost/", runScripts: "dangerously", pretendToBeVisual: true });
const { window } = dom;
const { document } = window;
window.alert = () => {}; window.print = () => {};
window.HTMLElement.prototype.scrollIntoView = () => {};

// Emulated vertical layout: a block's height comes from data-h (paragraphs)
// or its gutter padding (lp-gap: padTop + 26 + padBottom); offsetTop is the
// stacked sum of all previous siblings, exactly like real block flow with
// zero margins. This lets paginate()'s measure-insert-remeasure loop run
// against true geometry.
function vh(el) {
  if (!el.getAttribute) return 0;
  if ((el.className || "").indexOf("lp-gap") >= 0) {
    const pt = parseFloat(el.style.paddingTop) || 0;
    const pb = parseFloat(el.style.paddingBottom) || 0;
    return pt + 26 + pb;
  }
  return parseFloat(el.getAttribute("data-h")) || 0;
}
Object.defineProperty(window.HTMLElement.prototype, "offsetHeight", {
  get() { return vh(this); }, configurable: true,
});
Object.defineProperty(window.HTMLElement.prototype, "offsetTop", {
  get() {
    let t = 96; // page content starts below the top margin (padding-top)
    for (let n = this.parentNode && this.parentNode.firstChild; n && n !== this; n = n.nextSibling)
      if (n.nodeType === 1) t += vh(n);
    return t;
  }, configurable: true,
});

const results = [];
const check = (n, ok, x) => results.push([ok ? "PASS" : "FAIL", n, x || ""]);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

(async () => {
  await sleep(50);
  window.location.hash = "writer";
  await sleep(30);
  document.querySelector("button.primary").click();
  await sleep(30);
  const page = document.querySelector(".page[contenteditable]");

  // Letter portrait, 1in margins: h=1056, m=96, contentH=864, gutter=26.
  // Stride between paper tops = 1056 + 26 = 1082; every page's content top
  // must land at k*1082 + 96.
  const STRIDE = 1082, M = 96;

  // ---- ten 200px paragraphs: 4 fit per page (800 <= 864) -> 3 pages ----
  page.innerHTML = Array.from({ length: 10 }, (_, i) => `<p data-h="200">b${i}</p>`).join("");
  page.dispatchEvent(new window.Event("input", { bubbles: true }));
  await sleep(400); // paginate debounce 250ms

  let gaps = [...page.querySelectorAll(".lp-gap")];
  check("10x200: two breaks -> 3 pages", gaps.length === 2, `gaps=${gaps.length}`);
  check("10x200: labels sequential", gaps.map(g => g.getAttribute("data-label")).join("|") === "Page 2|Page 3",
    gaps.map(g => g.getAttribute("data-label")).join("|"));
  const tops = [...page.children].filter(c => c.tagName === "P").map(p => p.offsetTop);
  check("10x200: breaks before b4 and b8",
    page.children[4].className === "lp-gap" && page.children[9].className === "lp-gap",
    [...page.children].map(c => c.tagName === "P" ? "p" : "G").join(""));
  const onGrid = tops.filter(t => (t - M) % STRIDE === 0);
  check("10x200: pages 2+3 start exactly at top margin",
    tops[4] === STRIDE + M && tops[8] === 2 * STRIDE + M, `t4=${tops[4]} t8=${tops[8]} (want ${STRIDE + M}, ${2 * STRIDE + M})`);
  check("10x200: first block stays at page 1 top margin", tops[0] === M, `t0=${tops[0]}`);
  const g0 = gaps[0];
  check("10x200: gap padding = fill+bottom-margin / top-margin",
    parseFloat(g0.style.paddingTop) === (M + 864 - tops[3] - 200) + M && parseFloat(g0.style.paddingBottom) === M,
    `pt=${g0.style.paddingTop} pb=${g0.style.paddingBottom}`);

  // ---- tall block: [200, 2000, 200] -> page 2 stretches, break after ----
  page.innerHTML = `<p data-h="200">a</p><p data-h="2000">tall</p><p data-h="200">z</p>`;
  page.dispatchEvent(new window.Event("input", { bubbles: true }));
  await sleep(400);
  gaps = [...page.querySelectorAll(".lp-gap")];
  const kids = [...page.children];
  const tTall = kids.find(k => k.textContent === "tall").offsetTop;
  const tZ = kids.find(k => k.textContent === "z").offsetTop;
  check("tall: two breaks, no runaway loop", gaps.length === 2, `gaps=${gaps.length}`);
  check("tall: tall block starts page 2 at its top margin", tTall === STRIDE + M, `t=${tTall}`);
  check("tall: next block breaks immediately after tall, margins kept",
    tZ === tTall + 2000 + M + 26 + M, `tZ=${tZ} want=${tTall + 2000 + M + 26 + M}`);

  // ---- continuous mode drops every gap ----
  const sel = [...page.parentNode.firstChild.querySelectorAll("select")].find(s => s.title === "Paper size");
  sel.value = "none";
  sel.dispatchEvent(new window.Event("change", { bubbles: true }));
  await sleep(50);
  check("continuous: zero gaps remain", page.querySelectorAll(".lp-gap").length === 0);

  let fails = 0;
  for (const [st, n, x] of results) { if (st === "FAIL") fails++; console.log(`${st}  ${n}${x ? "   [" + x + "]" : ""}`); }
  console.log(fails ? `\n${fails} FAILURES` : "\nALL GEOMETRY PASS");
  process.exit(fails ? 1 : 0);
})().catch((e) => { console.error("CRASH:", e); process.exit(2); });
